UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "Initial": {
        "All": "select result->''score''->>''decisiondetails'' as \\"decisiondetails\\", ilivemessageid as \\"ILiveMessageID\\", vcmsgid as \\"UniqueID\\", vcclassname as \\"Class\\", dttrxntime  as \\"Time\\", dobservationamount as \\"Amount\\", score as \\"Score\\",  case when result->>''status''=''Failed'' then ''false'' when result->>''status''=''Success'' then ''true'' when result->>''status'' IS NULL then CASE WHEN score > 0 THEN ''false'' WHEN score = 0  THEN ''true'' else NULL end end as \\"FRMPass\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", null as \\"FailedRule\\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \\"PayerName\\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as  \\"PayeeName\\", cast(observations-> ''txn''->>''type'' as text) as \\"Txn Type\\", ipayeemccid as \\"Payee MCC\\",cast(observations-> ''txn''->''attribs''->''skip_processing'' as int) as \\"Skip Processing\\" from analytics.trans where vcclassname in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and  iorgid =:orgid and mappingtype = ''TransactionClass'') (select vcclassname FROM ui.transactionclasses where (iclassid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid))  AND (score >= :score OR score IS NULL)  and dtcreateddatetime BETWEEN ((CURRENT_TIMESTAMP - INTERVAL ''1 day'') at time zone :timeZone ) AND CURRENT_TIMESTAMP at time zone :timeZone and itenantid = :tenantid order by ilivemessageid desc limit 50;",
        "Other": "select result->''score''->>''decisiondetails'' as \\"decisiondetails\\", ilivemessageid as \\"ILiveMessageID\\", vcmsgid as \\"UniqueID\\", vcclassname as \\"Class\\", dttrxntime  as \\"Time\\", dobservationamount as \\"Amount\\", score as \\"Score\\",  case when result->>''status''=''Failed'' then ''false'' when result->>''status''=''Success'' then ''true'' when result->>''status'' IS NULL then CASE WHEN score > 0 THEN ''false'' WHEN score = 0  THEN ''true'' else NULL end end as \\"FRMPass\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", null as \\"FailedRule\\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \\"PayerName\\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as  \\"PayeeName\\", cast(observations-> ''txn''->>''type'' as text) as \\"Txn Type\\", ipayeemccid as \\"Payee MCC\\",cast(observations-> ''txn''->''attribs''->''skip_processing'' as int) as \\"Skip Processing\\" from analytics.trans where (score >= :score OR score IS NULL)  and dtcreateddatetime BETWEEN ((CURRENT_TIMESTAMP - INTERVAL ''1 day'') at time zone :timeZone ) AND CURRENT_TIMESTAMP at time zone :timeZone and vcclassname  = :className and itenantid = :tenantid order by ilivemessageid desc limit 50;"
    },
    "Refresh": {
        "All": " select result->''score''->>''decisiondetails'' as \\"decisiondetails\\", ilivemessageid as \\"ILiveMessageID\\", vcmsgid as \\"UniqueID\\", vcclassname as \\"Class\\", dttrxntime  as \\"Time\\", dobservationamount as \\"Amount\\", score as \\"Score\\",  case when result->>''status''=''Failed'' then ''false'' when result->>''status''=''Success'' then ''true'' when result->>''status'' IS NULL then CASE WHEN score > 0 THEN ''false'' WHEN score = 0  THEN ''true'' else NULL end end as \\"FRMPass\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", null as \\"FailedRule\\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \\"PayerName\\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as  \\"PayeeName\\", cast(observations-> ''txn''->>''type'' as text) as \\"Txn Type\\", ipayeemccid as \\"Payee MCC\\",cast(observations-> ''txn''->''attribs''->''skip_processing'' as int) as \\"Skip Processing\\" from analytics.trans where vcclassname in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and  iorgid =:orgid and mappingtype = ''TransactionClass'') (select vcclassname FROM ui.transactionclasses where (iclassid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid)) AND (score >= :score OR score IS NULL) and dtcreateddatetime BETWEEN ((CURRENT_TIMESTAMP - INTERVAL ''1 day'') at time zone :timeZone ) AND CURRENT_TIMESTAMP at time zone :timeZone and ilivemessageid > :iLiveMessageID and itenantid = :tenantid order by ilivemessageid desc limit 1000;",
        "Other": "select result->''score''->>''decisiondetails'' as \\"decisiondetails\\", ilivemessageid as \\"ILiveMessageID\\", vcmsgid as \\"UniqueID\\", vcclassname as \\"Class\\", dttrxntime  as \\"Time\\", dobservationamount as \\"Amount\\", score as \\"Score\\",  case when result->>''status''=''Failed'' then ''false'' when result->>''status''=''Success'' then ''true'' when result->>''status'' IS NULL then CASE WHEN score > 0 THEN ''false'' WHEN score = 0  THEN ''true'' else NULL end end as \\"FRMPass\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", null as \\"FailedRule\\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \\"PayerName\\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as  \\"PayeeName\\", cast(observations-> ''txn''->>''type'' as text) as \\"Txn Type\\", ipayeemccid as \\"Payee MCC\\",cast(observations-> ''txn''->''attribs''->''skip_processing'' as int) as \\"Skip Processing\\" from analytics.trans  where (score >= :score OR score IS NULL)  and dtcreateddatetime BETWEEN ((CURRENT_TIMESTAMP - INTERVAL ''1 day'') at time zone :timeZone ) AND CURRENT_TIMESTAMP at time zone :timeZone and vcclassname  = :className and ilivemessageid > :iLiveMessageID and itenantid = :tenantid order by ilivemessageid desc limit 1000;"
    }
}
