idashboardqueryid = 55 and itenantid in (6,7,20);

UPDATE ui.dashboardquery SET
vcdashboardquery =  E'  {
    "All" :{
      "ClosedOn":"select  CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_row''->''fields''->>''network_score'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_row''->''fields''->>''network_score'' END as \\"Network Score\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->>''class'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->>''class'' END as \\"Class (CUB or USFB)\\" , accountid.long_ as \\"Account ID\\", null as \\"Document Number\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_row''->''fields''->>''last_four_digits'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_row''->''fields''->>''last_four_digits'' END  as \\"Last 4 digits of card\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''payerVPA''->>''vpaName'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''payerVPA''->>''vpaName'' END  as \\"Customer Name\\", TransactionAmount.double_ / 100 as \\"Transaction Amount\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->>''ts'' as timestamp) at time zone ''Asia/Kolkata'' at time zone  :timeZone else cast(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->>''ts'' as timestamp) at time zone ''Asia/Kolkata'' at time zone  :timeZone END  as \\"Authorization Timestamp\\", riskscore.long_ as \\"FRM Score\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_row''->''fields''->>''response_code'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_row''->''fields''->>''response_code'' END as \\"Authorization Response Code\\" , CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then CASE WHEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_row''->''fields''->''original_network_data''->>''response_code'' = ''00'' THEN ''Approved'' ELSE ''Declined'' END else CASE WHEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_row''->''fields''->''original_network_data''->>''response_code'' = ''00'' THEN ''Approved'' ELSE ''Declined'' END END as \\"Approved/Declined\\" , CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->>''pos_entry_mode'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->>''pos_entry_mode'' END  as \\"POS Entry Mode\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''payee''->>''mcc'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''payee''->>''mcc'' END  as \\"Merchant Category Code (MCC)\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''payeeVPA''->>''vpaName'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''payeeVPA''->>''vpaName'' END as \\"Merchant Name\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_row''->''fields''->>''merchant_state_or_country_code'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_row''->''fields''->>''merchant_state_or_country_code'' END as \\"Merchant Location\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_row''->''fields''->>''merchant_state_or_country_code'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_row''->''fields''->>''merchant_state_or_country_code'' END as \\"Card Acceptor Country Code\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->>''moto_eci_recurring'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->>''moto_eci_recurring'' END as \\"MOTO/ECI/Recurring\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''payer''->>''currency'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''payer''->>''currency'' END as \\"Issuer Currency Code\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_row''->''fields''->''original_network_data''->>''f37_retrieval_reference_number'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_row''->''fields''->''original_network_data''->>''f37_retrieval_reference_number'' END as \\"Retrieval Reference Number\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->>''id'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->>''id'' END as \\"Transaction ID\\", CASE WHEN  closedby.assignee_ is not null THEN userinfo.email_ ELSE ''Auto Closed'' END as \\"Statused By User ID\\", CASE WHEN  closedby.assignee_ is not null THEN userinfo.first_ ||'' '' || userinfo.last_ ELSE ''Auto Closed'' END as \\"Agent Name\\", hiproinst.end_time_  as  \\"Alert Status change Timestamp (Asia/Calcutta)\\", CASE when actionvar.text_ = ''Value_Update_Whitelist'' THEN ''Update Whitelist'' when actionvar.text_ = ''Value_Fraud'' THEN ''Report Fraud to CRM'' when actionvar.text_ = ''Value_Close'' THEN ''False Positive, Close Case'' END as \\"Action taken or status\\", triggeredtype.text_ as \\"Rule type\\", replace(replace(replace(rulename.text_, ''['', ''''), '']'',''''),''\\"'','''') as \\"Rule Name\\" from camunda.act_hi_procinst hiproinst full outer join camunda.act_hi_varinst actionvar on actionvar.proc_inst_id_ = hiproinst.proc_inst_id_ and actionvar.name_ = ''Action'' full outer join camunda.act_hi_taskinst closedby on closedby.id_ = (select id_ from camunda.act_hi_taskinst where proc_inst_id_ = hiproinst.proc_inst_id_ order by end_time_ desc limit 1) full outer join camunda.act_hi_varinst accountid on accountid.proc_inst_id_ = hiproinst.proc_inst_id_ and accountid.name_ = ''accountid'' full outer join camunda.act_hi_varinst riskscore on riskscore.proc_inst_id_ = hiproinst.proc_inst_id_ and riskscore.name_ = ''RiskScore'' full outer join camunda.act_hi_varinst  TransactionAmount on TransactionAmount.proc_inst_id_ = hiproinst.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' full outer join camunda.act_hi_varinst triggeredtype  on triggeredtype.proc_inst_id_ = hiproinst.proc_inst_id_ and triggeredtype.name_ = ''triggeredtype'' full outer join camunda.act_hi_varinst  Txn on Txn.proc_inst_id_ = hiproinst.proc_inst_id_ and Txn.name_ = ''Transaction'' full outer join camunda.act_ge_bytearray Txnorg on Txnorg.id_ = Txn.bytearray_id_ full outer join camunda.act_hi_varinst rulename on rulename.proc_inst_id_ = hiproinst.proc_inst_id_ and rulename.name_ = ''failedRules'' full outer join camunda.act_id_user userinfo on userinfo.id_ = closedby.assignee_ where cast(hiproinst.end_time_ as date) between cast(:StartDate as date) and cast(:EndDate as date) and hiproinst.state_ = ''COMPLETED'' and hiproinst.proc_def_key_ in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser AND iorgid =:orgid  and mappingtype = ''Workflow'') (select workflowkey FROM ui.workflowmasters where (workflowid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid and is_filter_display=true)) and hiproinst.tenant_id_= :tenantidstr",
      "CreatedOn":"select CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_row''->''fields''->>''network_score'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_row''->''fields''->>''network_score'' END as \\"Network Score\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->>''class'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->>''class'' END as \\"Class (CUB or USFB)\\" , accountid.long_ as \\"Account ID\\", null as \\"Document Number\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_row''->''fields''->>''last_four_digits'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_row''->''fields''->>''last_four_digits'' END  as \\"Last 4 digits of card\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''observations''->''payerVPA''->>''vpaName'' else  cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''payerVPA''->>''vpaName'' END  as \\"Customer Name\\", TransactionAmount.double_ / 100 as \\"Transaction Amount\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->>''ts'' as timestamp) at time zone ''Asia/Kolkata'' at time zone  :timeZone else cast(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->>''ts'' as timestamp) at time zone ''Asia/Kolkata'' at time zone  :timeZone END  as \\"Authorization Timestamp\\", riskscore.long_ as \\"FRM Score\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_row''->''fields''->>''response_code'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_row''->''fields''->>''response_code'' END as \\"Authorization Response Code\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then CASE WHEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_row''->''fields''->''original_network_data''->>''response_code'' = ''00'' THEN ''Approved'' ELSE ''Declined'' END else CASE WHEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_row''->''fields''->''original_network_data''->>''response_code'' = ''00'' THEN ''Approved'' ELSE ''Declined'' END END as \\"Approved/Declined\\" , CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->>''pos_entry_mode'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->>''pos_entry_mode'' END  as \\"POS Entry Mode\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''payee''->>''mcc'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''payee''->>''mcc'' END  as \\"Merchant Category Code (MCC)\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''payeeVPA''->>''vpaName'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''payeeVPA''->>''vpaName'' END as \\"Merchant Name\\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jso